(window.DOM_LAMLA=window.DOM_LAMLA||{})["lecture-6"]={"lecture":"lecture-6","chapters":[{"slug":"cerebral","must":[{"star":true,"html":"<strong>Continuous cerebral blood flow</strong> is essential because the brain stores almost no oxygen or glucose; a short interruption rapidly causes unconsciousness."},{"star":false,"html":"<strong>High cerebral oxygen demand</strong> makes the brain vulnerable to hypoxia because it uses a large share of cardiac output despite low body mass."},{"star":false,"html":"<strong>Hypoxic sensitivity</strong> is greatest in cortex, basal ganglia and thalamus; brainstem functions are relatively more resistant."},{"star":false,"html":"<strong>Glucose</strong> provides most cerebral energy because the brain depends on circulating fuel and takes up glucose without insulin."},{"star":false,"html":"<strong>Hypoglycaemia</strong> may produce convulsions or coma because neurons cannot sustain energy-dependent electrical activity without sufficient substrate."},{"star":false,"html":"<strong>Prolonged starvation</strong> allows some cerebral energy to come from ketone bodies made in the liver, reducing dependence on glucose."},{"star":false,"html":"<strong>Internal carotid arteries</strong> mainly supply anterior and middle cerebral territories, including much of the cerebral hemispheres."},{"star":false,"html":"<strong>Vertebral arteries</strong> unite into the basilar artery → posterior brain regions and brainstem receive a separate arterial inflow."},{"star":false,"html":"<strong>Circle of Willis</strong> joins carotid and vertebrobasilar circulations → collateral supply may compensate when an inflow artery narrows slowly."},{"star":false,"html":"<strong>Limited distal anastomoses</strong> leave cerebral territories vulnerable because arteries beyond the Circle of Willis have few effective alternative pathways."},{"star":false,"html":"<strong>Anterior cerebral artery</strong> supplies much of the medial frontal/parietal surface → obstruction particularly affects the opposite leg."},{"star":false,"html":"<strong>Middle cerebral artery</strong> supplies the lateral hemisphere → blockage often impairs opposite face/arm and dominant-hemisphere speech."},{"star":false,"html":"<strong>Posterior cerebral artery</strong> supplies the occipital cortex → obstruction can cause visual disturbance."},{"star":true,"html":"<strong>Cerebral autoregulation</strong> constricts arterioles when perfusion pressure rises and dilates them when pressure falls → flow stays relatively steady within limits."},{"star":false,"html":"<strong>Increased cerebral CO₂</strong> raises local H⁺ → cerebral arterioles dilate and blood flow increases."},{"star":false,"html":"<strong>Hyperventilation</strong> lowers arterial CO₂ → cerebral arterioles constrict and blood flow may fall enough to cause dizziness."},{"star":false,"html":"<strong>Severe cerebral hypoxia</strong> dilates cerebral arterioles because inadequate oxygen delivery demands increased blood flow."},{"star":false,"html":"<strong>Neurovascular coupling</strong> increases flow to active brain regions because local metabolic activity generates vasodilator signals."},{"star":false,"html":"<strong>Cerebral innervation</strong> includes adrenergic, cholinergic and sensory nerves, but local chemical regulation dominates flow control."},{"star":false,"html":"<strong>Pain-sensitive cerebral vessels and meninges</strong> can generate headache because sensory nerves innervate them, unlike most brain tissue."},{"star":true,"html":"<strong>Monro–Kellie doctrine</strong> states brain, intracranial blood and CSF share a rigid skull → added volume ultimately raises intracranial pressure."},{"star":false,"html":"<strong>Compensatory intracranial shifts</strong> initially move CSF and venous blood out → small volume increases cause limited pressure rises."},{"star":false,"html":"<strong>Exhausted intracranial reserve</strong> makes pressure rise steeply → cerebral vessels are compressed and flow becomes endangered."},{"star":false,"html":"<strong>Cerebral perfusion pressure</strong> equals mean arterial pressure minus intracranial pressure → rising ICP can reduce brain perfusion despite unchanged arm BP."},{"star":false,"html":"<strong>Cushing reflex</strong> begins with severe brainstem ischaemia → sympathetic vasoconstriction raises BP, and baroreceptors subsequently slow the heart."},{"star":false,"html":"<strong>Cushing triad</strong> combines hypertension, bradycardia and irregular breathing → a late warning of critically raised intracranial pressure."},{"star":false,"html":"<strong>Dura mater</strong> forms the tough outer meningeal covering; arachnoid mater lies beneath it and pia follows the brain surface."},{"star":false,"html":"<strong>Subarachnoid space</strong> contains CSF and cerebral vessels between arachnoid and pia; normal subdural space is only potential."},{"star":false,"html":"<strong>Choroid plexus</strong> produces most CSF in the cerebral ventricles → continuous flow replaces CSF several times daily."},{"star":true,"html":"<strong>CSF flow</strong> follows lateral ventricles → Monro → third ventricle → cerebral aqueduct → fourth ventricle → Magendie/Luschka → subarachnoid space → arachnoid villi."},{"star":false,"html":"<strong>Arachnoid villi</strong> absorb CSF into dural venous sinuses → waste and water return to the bloodstream."},{"star":false,"html":"<strong>CSF cushioning</strong> protects brain tissue from impacts because fluid and arachnoid trabeculae reduce movement-related injury."},{"star":false,"html":"<strong>CSF buoyancy</strong> markedly reduces the brain's effective weight → pressure on its base is much smaller than in air."},{"star":false,"html":"<strong>CSF waste removal</strong> carries metabolites and some drugs into venous blood through continuous fluid turnover."},{"star":false,"html":"<strong>CSF hormone transport</strong> permits substances released into the fluid to reach distant brain regions."},{"star":false,"html":"<strong>Non-communicating hydrocephalus</strong> follows obstruction inside the ventricular pathway → CSF accumulates upstream and ventricles enlarge."},{"star":false,"html":"<strong>Communicating hydrocephalus</strong> follows impaired arachnoid-villus absorption despite open communication between ventricles and subarachnoid space."},{"star":false,"html":"<strong>Lumbar puncture</strong> samples CSF from the lower spinal subarachnoid space below the spinal cord's end."},{"star":false,"html":"<strong>Lumbar puncture hazard</strong> arises when raised ICP from a mass creates a dangerous pressure gradient → brain herniation may follow fluid removal."},{"star":true,"html":"<strong>Blood–brain barrier</strong> is formed mainly by tight junctions between brain capillary endothelial cells → most blood chemicals cannot pass freely."},{"star":false,"html":"<strong>Astrocyte endfeet and pericytes</strong> help maintain the cerebral endothelial barrier and stable extracellular conditions for neurons."},{"star":false,"html":"<strong>Lipid-soluble substances and gases</strong> cross the BBB comparatively easily because they diffuse through endothelial cell membranes."},{"star":false,"html":"<strong>Glucose entry to brain</strong> requires GLUT1 transporters because glucose cannot freely cross endothelial tight junctions."},{"star":false,"html":"<strong>Plasma proteins and bound drugs</strong> cross the BBB poorly → circulating substances may not reach neuronal tissue."},{"star":false,"html":"<strong>BBB disruption</strong> in infection, inflammation, injury or tumours increases entry of normally excluded blood substances."},{"star":false,"html":"<strong>Choroid-plexus blood–CSF barrier</strong> is chiefly epithelial rather than endothelial → it differs anatomically from the BBB."},{"star":false,"html":"<strong>Ischaemic stroke</strong> results from thrombus, embolus or atherosclerotic blockage → downstream brain tissue loses blood and may die."},{"star":false,"html":"<strong>Haemorrhagic stroke</strong> results from arterial rupture, sometimes an aneurysm → bleeding injures tissue and can raise ICP."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Brain mass relative to body</td>\n  <td>About 2%</td>\n  <td>Small organ with disproportionately high metabolic demand.</td>\n</tr>\n<tr>\n  <td>Fraction of resting cardiac output used by brain</td>\n  <td>About 15%</td>\n  <td>Demonstrates continuous perfusion requirement.</td>\n</tr>\n<tr>\n  <td>Fraction of total body oxygen used by brain</td>\n  <td>About 20%</td>\n  <td>Explains extreme sensitivity to interrupted oxygen delivery.</td>\n</tr>\n<tr>\n  <td>Time without cerebral flow before loss of consciousness</td>\n  <td>About 10 seconds</td>\n  <td>Very short cerebral ischaemia is clinically apparent.</td>\n</tr>\n<tr>\n  <td>Main cerebral fuel contribution</td>\n  <td>About 90% glucose</td>\n  <td>Hypoglycaemia has major neurological consequences.</td>\n</tr>\n<tr>\n  <td>Classical cerebral autoregulation range</td>\n  <td>MAP about 60–150 mmHg</td>\n  <td>Flow remains near constant only within an approximate range.</td>\n</tr>\n<tr>\n  <td>Brain mass within skull</td>\n  <td>About 1400 g</td>\n  <td>Major fixed component of Monro–Kellie intracranial volume.</td>\n</tr>\n<tr>\n  <td>Intracranial blood and CSF used in approved illustration</td>\n  <td>About 75 mL each</td>\n  <td>Extra intracranial volume must displace existing contents.</td>\n</tr>\n<tr>\n  <td>Example cerebral perfusion calculation</td>\n  <td>MAP 90 − ICP 10 = CPP 80 mmHg</td>\n  <td>CPP may fall even with unchanged systemic pressure.</td>\n</tr>\n<tr>\n  <td>ICP associated with lecture's Cushing response</td>\n  <td>Above about 33 mmHg</td>\n  <td>Severe pressure can cause medullary ischaemia.</td>\n</tr>\n<tr>\n  <td>Total CSF volume</td>\n  <td>About 150 mL</td>\n  <td>Small circulating reservoir undergoes repeated replacement.</td>\n</tr>\n<tr>\n  <td>CSF production</td>\n  <td>About 550 mL/day</td>\n  <td>CSF turns over several times each day.</td>\n</tr>\n<tr>\n  <td>Brain's effective weight when suspended in CSF</td>\n  <td>About 50 g</td>\n  <td>Buoyancy reduces force on brain structures.</td>\n</tr>\n<tr>\n  <td>Lumbar CSF pressure when lying</td>\n  <td>70–180 mm CSF</td>\n  <td>Normal reference range used in the lecture.</td>\n</tr>\n<tr>\n  <td>CSF protein</td>\n  <td>About 20 mg/dL</td>\n  <td>Far lower than plasma because of restricted passage.</td>\n</tr>\n<tr>\n  <td>CSF glucose</td>\n  <td>About 64 mg/dL</td>\n  <td>Roughly two-thirds of blood glucose.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Autoregulation and CO₂</strong>: Cerebral perfusion pressure changes → arterioles constrict or dilate to stabilise flow; if local CO₂ increases → H⁺ rises → cerebral arterioles dilate → flow increases.</li>\n<li><strong>Raised intracranial pressure</strong>: Haemorrhage or swelling adds volume inside rigid skull → CSF/venous reserve is exhausted → ICP rises → CPP falls → medullary ischaemia triggers hypertension → baroreflex bradycardia.</li>\n<li><strong>CSF pathway</strong>: Choroid plexus secretes fluid into lateral ventricles → Monro → third ventricle → Sylvius → fourth ventricle → Magendie/Luschka → subarachnoid space → arachnoid-villus absorption.</li>\n<li><strong>Cerebral stroke</strong>: Cerebral artery occlusion or rupture → oxygen delivery falls or local bleeding increases → neuronal dysfunction and injury → focal neurological deficit corresponding to the affected artery.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Anterior cerebral artery</strong></th>\n  <th><strong>Middle cerebral artery</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Main surface supplied</td>\n  <td>Medial frontal/parietal cortex.</td>\n  <td>Lateral cerebral hemisphere.</td>\n</tr>\n<tr>\n  <td>Typical motor deficit</td>\n  <td>Contralateral leg predominance.</td>\n  <td>Contralateral face and arm predominance.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Communicating hydrocephalus</strong></th>\n  <th><strong>Non-communicating hydrocephalus</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Main defect</td>\n  <td>Arachnoid villi fail to absorb CSF adequately.</td>\n  <td>Ventricular outflow is blocked internally.</td>\n</tr>\n<tr>\n  <td>Communication</td>\n  <td>Ventricular route remains open.</td>\n  <td>CSF cannot pass the obstructed segment.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Blood–brain barrier</strong></th>\n  <th><strong>Blood–CSF barrier</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Main anatomical seal</td>\n  <td>Tight junctions of brain capillary endothelium.</td>\n  <td>Tight junctions of choroid-plexus epithelium.</td>\n</tr>\n<tr>\n  <td>Role</td>\n  <td>Restricts substances entering brain interstitial fluid.</td>\n  <td>Regulates exchange between blood and ventricular CSF.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Ischaemic stroke</strong></th>\n  <th><strong>Haemorrhagic stroke</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Immediate lesion</td>\n  <td>Blood vessel is blocked.</td>\n  <td>Blood vessel ruptures.</td>\n</tr>\n<tr>\n  <td>Typical mechanism</td>\n  <td>Plaque, thrombus or embolus.</td>\n  <td>Rupture, sometimes of an aneurysm.</td>\n</tr>\n<tr>\n  <td>ICP issue</td>\n  <td>May increase if infarcted tissue swells.</td>\n  <td>Extra intracranial blood can directly raise ICP.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Brain oxygen stores</strong> can sustain several minutes of flow interruption → Truth: The brain stores very little oxygen and unconsciousness follows rapidly.</li>\n<li>Trap: <strong>Circle of Willis</strong> guarantees protection from every cerebral artery blockage → Truth: The ring may be incomplete and distal arteries have few anastomoses.</li>\n<li>Trap: <strong>Hyperventilation</strong> raises cerebral flow by adding oxygen → Truth: Falling CO₂ constricts cerebral arterioles and can cause dizziness.</li>\n<li>Trap: <strong>A normal arm pressure</strong> ensures cerebral perfusion → Truth: High intracranial pressure reduces CPP even when MAP is unchanged.</li>\n<li>Trap: <strong>Cushing bradycardia</strong> means the brain initially lowered sympathetic output → Truth: Severe ICP triggers sympathetic hypertension, followed by baroreflex slowing.</li>\n<li>Trap: <strong>CSF</strong> normally fills the subdural space → Truth: CSF occupies the subarachnoid space; normal subdural space is potential.</li>\n<li>Trap: <strong>Communicating hydrocephalus</strong> means a blocked cerebral aqueduct → Truth: Open ventricular pathways with reduced absorption define communicating disease.</li>\n<li>Trap: <strong>Glucose</strong> crosses the BBB by unrestricted diffusion → Truth: It uses a carrier, chiefly GLUT1.</li>\n<li>Trap: <strong>Every stroke</strong> is a thrombotic blockage → Truth: Haemorrhagic stroke follows vessel rupture and may increase ICP.</li>\n</ul>\n"},{"slug":"coronary","must":[{"star":true,"html":"<strong>Separate coronary arteries</strong> nourish thick myocardium because oxygen cannot diffuse sufficiently from blood inside the heart chambers."},{"star":false,"html":"<strong>Aortic sinuses</strong> give rise to right and left coronary arteries immediately above the aortic valve cusps."},{"star":true,"html":"<strong>High resting oxygen extraction</strong> means myocardium must increase coronary flow when work rises because little additional extraction reserve remains."},{"star":false,"html":"<strong>Left anterior descending artery</strong> supplies anterior left ventricle and much of the interventricular septum → its obstruction threatens these regions."},{"star":false,"html":"<strong>Left circumflex artery</strong> chiefly supplies the lateral left ventricular wall."},{"star":false,"html":"<strong>Right coronary artery</strong> mainly supplies the right ventricle and commonly the inferior ventricular wall."},{"star":false,"html":"<strong>Coronary dominance</strong> is defined by the origin of the posterior descending artery, not which vessel supplies most of the heart."},{"star":false,"html":"<strong>Coronary venous drainage</strong> mostly enters the coronary sinus and then right atrium; some veins drain directly into chambers."},{"star":true,"html":"<strong>Left ventricular systole</strong> compresses intramyocardial coronary vessels → left ventricular blood flow becomes greatest during diastole."},{"star":false,"html":"<strong>Right ventricular coronary flow</strong> occurs in both systole and diastole because right ventricular contraction compresses vessels less strongly."},{"star":false,"html":"<strong>Left coronary driving pressure</strong> is approximately aortic diastolic minus left ventricular diastolic pressure → low aortic pressure reduces coronary perfusion."},{"star":false,"html":"<strong>High left ventricular filling pressure</strong> reduces coronary driving pressure because it narrows the diastolic pressure gradient across the ventricular wall."},{"star":false,"html":"<strong>Subendocardium</strong> is most prone to ischaemia because high cavity pressure compresses its vessels strongly during contraction."},{"star":false,"html":"<strong>Aortic stenosis</strong> raises left ventricular pressure and oxygen demand → subendocardial vessels are further compressed."},{"star":false,"html":"<strong>Myocardial oxygen demand</strong> rises with heart rate, contractility and wall tension → coronary delivery must increase proportionately."},{"star":true,"html":"<strong>Coronary active hyperaemia</strong> follows myocardial activity → adenosine and other metabolites dilate coronary arterioles and increase flow."},{"star":false,"html":"<strong>Low O₂, K⁺ and endothelial nitric oxide</strong> contribute to metabolic coronary vasodilatation as myocardial oxygen demand rises."},{"star":false,"html":"<strong>Direct sympathetic α stimulation</strong> constricts coronary vessels, but this does not usually determine the net exercise response."},{"star":false,"html":"<strong>Sympathetic β₁ stimulation</strong> increases cardiac work → greater metabolite production produces net coronary vasodilatation."},{"star":false,"html":"<strong>Tachycardia</strong> increases myocardial oxygen demand and shortens diastole → both changes favour coronary ischaemia."},{"star":false,"html":"<strong>Diastolic shortening</strong> reduces the time for left ventricular coronary filling, especially when coronary arteries are narrowed."},{"star":true,"html":"<strong>Coronary flow reserve</strong> is the ability to increase flow above resting levels by further arteriolar dilatation."},{"star":false,"html":"<strong>Fixed coronary narrowing</strong> causes distal arterioles to dilate even at rest → less reserve remains available during exercise."},{"star":false,"html":"<strong>Exertional angina</strong> occurs when myocardial demand exceeds limited coronary supply → temporary ischaemia causes chest pain without irreversible cell death."},{"star":false,"html":"<strong>Myocardial infarction</strong> follows prolonged severe ischaemia → cardiac muscle cells die rather than simply becoming temporarily underperfused."},{"star":false,"html":"<strong>Plaque rupture and thrombosis</strong> may suddenly obstruct coronary flow → myocardial infarction can occur despite previously compensated narrowing."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Myocardial oxygen extraction at rest</td>\n  <td>About 70%</td>\n  <td>Increased demand normally requires more flow rather than much more extraction.</td>\n</tr>\n<tr>\n  <td>Typical coronary flow reserve</td>\n  <td>About 4–5 times resting flow</td>\n  <td>Healthy coronary arterioles can markedly increase supply.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Diastolic coronary perfusion</strong>: Ventricular systole compresses left myocardial vessels → intramuscular flow falls → ventricular relaxation releases compression → aortic diastolic pressure drives coronary blood into the left ventricle.</li>\n<li><strong>Active coronary hyperaemia</strong>: Heart rate or contractility increases → oxygen demand and ATP turnover increase → adenosine and local vasodilators accumulate → coronary arterioles widen → myocardial blood flow rises.</li>\n<li><strong>Angina from narrowed artery</strong>: Coronary lumen narrows → downstream arterioles dilate at rest to preserve baseline flow → reserve becomes limited → exercise raises demand → ischaemic angina appears.</li>\n<li><strong>Tachycardia and infarction risk</strong>: Faster heart → oxygen demand rises while diastole shortens → supply/demand mismatch worsens → prolonged severe occlusion can cause irreversible myocardial death.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Left ventricular coronary flow</strong></th>\n  <th><strong>Right ventricular coronary flow</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Main perfusion time</td>\n  <td>Predominantly diastole.</td>\n  <td>Both systole and diastole.</td>\n</tr>\n<tr>\n  <td>Reason</td>\n  <td>High LV contraction pressure compresses vessels.</td>\n  <td>Lower RV contraction pressure causes less compression.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Angina pectoris</strong></th>\n  <th><strong>Myocardial infarction</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Injury</td>\n  <td>Temporary, reversible myocardial ischaemia.</td>\n  <td>Irreversible death of myocardial cells.</td>\n</tr>\n<tr>\n  <td>Common trigger</td>\n  <td>Exertional demand exceeds restricted reserve.</td>\n  <td>Prolonged severe obstruction or thrombosis.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Coronary α effect</strong></th>\n  <th><strong>Coronary β₁-mediated effect</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Mechanism</td>\n  <td>Direct vasoconstriction of coronary vessels.</td>\n  <td>Greater cardiac work increases metabolic vasodilator release.</td>\n</tr>\n<tr>\n  <td>Exercise net effect</td>\n  <td>Usually outweighed by metabolic signals.</td>\n  <td>Net coronary flow normally increases.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Left coronary flow</strong> is greatest in systole, when aortic pressure peaks → Truth: Contraction squeezes the vessels inside the left ventricular wall, so most left coronary flow comes in diastole.</li>\n<li>Trap: <strong>Coronary dominance</strong> means the dominant artery supplies the entire heart → Truth: It identifies which coronary artery gives the posterior descending branch.</li>\n<li>Trap: <strong>More myocardial work</strong> is met mainly by greater oxygen extraction → Truth: The heart already extracts much oxygen; coronary flow must increase.</li>\n<li>Trap: <strong>Faster heart rate</strong> always improves myocardial oxygen supply → Truth: Tachycardia shortens diastolic perfusion and increases oxygen demand.</li>\n<li>Trap: <strong>Direct α vasoconstriction</strong> means exercise must reduce coronary flow → Truth: Metabolic dilation from increased work usually dominates.</li>\n<li>Trap: <strong>Angina</strong> necessarily means permanent muscle death → Truth: Angina is transient ischaemia; sustained severe ischaemia causes infarction.</li>\n<li>Trap: <strong>Subendocardium</strong> is safest because it lies near chamber blood → Truth: Wall compression makes it especially vulnerable to reduced coronary supply.</li>\n</ul>\n"},{"slug":"pulmonary","must":[{"star":true,"html":"<strong>Pulmonary circulation</strong> carries right ventricular blood through lung capillaries for gas exchange → pulmonary veins return it to the left atrium."},{"star":false,"html":"<strong>Bronchial circulation</strong> arises from the aorta and nourishes conducting airways and other supporting lung tissues."},{"star":false,"html":"<strong>Bronchial venous mixing</strong> slightly reduces arterial oxygenation because some deoxygenated bronchial drainage enters pulmonary veins."},{"star":true,"html":"<strong>Equal ventricular outputs</strong> flow through pulmonary and systemic circuits in series, but the pulmonary circuit needs a much lower pressure gradient."},{"star":false,"html":"<strong>Low pulmonary vascular resistance</strong> results from short, wide, compliant vessels and many parallel capillary pathways."},{"star":false,"html":"<strong>Pulmonary recruitment</strong> opens previously unperfused capillaries as output increases → total circuit resistance falls."},{"star":false,"html":"<strong>Pulmonary distension</strong> widens already perfused vessels during exercise → increased flow causes only a small pressure rise."},{"star":false,"html":"<strong>Low pulmonary capillary hydrostatic pressure</strong> limits outward filtration and helps protect the thin alveolar gas-exchange surface."},{"star":false,"html":"<strong>Plasma oncotic pressure</strong> opposes fluid leaving pulmonary capillaries → lymphatics can remove the small normal filtrate."},{"star":false,"html":"<strong>Pulmonary oedema in left failure</strong> develops when high left atrial pressure raises lung capillary pressure → filtration overwhelms lymphatic drainage."},{"star":false,"html":"<strong>Alveolar flooding</strong> impairs oxygen transfer because fluid increases the diffusion barrier between air and blood."},{"star":true,"html":"<strong>Gravity in upright lungs</strong> increases vascular pressure and perfusion towards the bases → apical blood flow remains lower."},{"star":false,"html":"<strong>West zone 1</strong> has alveolar pressure above arterial and venous pressure → compressed capillaries may carry no blood."},{"star":false,"html":"<strong>West zone 2</strong> has arterial pressure above alveolar pressure but venous pressure below it → flow depends on arterial-to-alveolar pressure."},{"star":false,"html":"<strong>West zone 3</strong> has arterial and venous pressures above alveolar pressure → capillaries stay open and flow continuously."},{"star":false,"html":"<strong>West zones</strong> are changing pressure relationships, not permanently fixed lung regions; posture and blood pressure can move their boundaries."},{"star":false,"html":"<strong>Supine posture</strong> reduces top-to-bottom pressure differences → pulmonary flow spreads more evenly than during upright posture."},{"star":false,"html":"<strong>Pulmonary blood reservoir</strong> expands when lying flat because blood redistributes from lower-body systemic veins into lung vessels."},{"star":false,"html":"<strong>Orthopnoea</strong> worsens in left failure because lying flat increases lung blood volume and pulmonary capillary hydrostatic pressure."},{"star":true,"html":"<strong>Hypoxic pulmonary vasoconstriction</strong> narrows vessels serving poorly ventilated alveoli → blood is redirected towards better ventilated units."},{"star":false,"html":"<strong>Hypoxic pulmonary constriction</strong> differs from systemic arteriolar control because low oxygen usually dilates systemic resistance vessels."},{"star":false,"html":"<strong>Raised local pulmonary CO₂/H⁺</strong> promotes vasoconstriction → perfusion shifts away from poorly ventilated alveoli."},{"star":false,"html":"<strong>Generalised alveolar hypoxia</strong> constricts vessels throughout both lungs → total resistance and pulmonary arterial pressure rise."},{"star":false,"html":"<strong>Persistent pulmonary vasoconstriction</strong> may cause pulmonary hypertension and increased right ventricular workload."},{"star":false,"html":"<strong>Pulmonary nitric oxide</strong> relaxes vascular smooth muscle → local pulmonary vessels dilate."},{"star":false,"html":"<strong>Pulmonary sympathetic stimulation</strong> can constrict lung vessels, although local oxygen control strongly affects regional distribution."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Pulmonary arterial pressure</td>\n  <td>About 25/8 mmHg; mean 15 mmHg</td>\n  <td>Far lower than systemic pressure despite similar flow.</td>\n</tr>\n<tr>\n  <td>Systemic arterial pressure for comparison</td>\n  <td>About 120/80 mmHg; mean 93 mmHg</td>\n  <td>Illustrates the much larger systemic driving pressure.</td>\n</tr>\n<tr>\n  <td>Pulmonary vascular resistance relative to systemic</td>\n  <td>About one-tenth</td>\n  <td>Supports right ventricular output with low pressure.</td>\n</tr>\n<tr>\n  <td>Resting cardiac output through either circuit</td>\n  <td>About 5 L/min</td>\n  <td>Right and left ventricles pump equal volumes in series.</td>\n</tr>\n<tr>\n  <td>Pulmonary capillary hydrostatic pressure</td>\n  <td>About 10 mmHg</td>\n  <td>Low outward fluid pressure normally limits oedema.</td>\n</tr>\n<tr>\n  <td>Plasma oncotic pressure</td>\n  <td>About 25 mmHg</td>\n  <td>Helps retain fluid inside pulmonary capillaries.</td>\n</tr>\n<tr>\n  <td>Pulmonary capillary pressure linked with oedema</td>\n  <td>Above about 25 mmHg</td>\n  <td>High pressure can overwhelm lymphatic clearance.</td>\n</tr>\n<tr>\n  <td>Blood shifted into lungs by lying down</td>\n  <td>About 400 mL</td>\n  <td>Explains increased congestion in left heart failure.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Exercise adaptation</strong>: Cardiac output increases → pulmonary capillaries recruit and distend → vascular resistance falls → much more blood passes with only a modest rise in pressure.</li>\n<li><strong>Pulmonary oedema</strong>: Left ventricle fails → left atrial and pulmonary venous pressure rise → capillary hydrostatic pressure increases → fluid filtration exceeds lymphatic removal → alveoli flood.</li>\n<li><strong>Local hypoxia</strong>: One alveolar region is poorly ventilated → alveolar oxygen falls → supplying pulmonary arterioles constrict → blood moves to better ventilated regions → ventilation/perfusion matching improves.</li>\n<li><strong>Global hypoxia</strong>: Many alveoli become hypoxic → widespread pulmonary vasoconstriction → resistance and pulmonary pressure rise → right ventricular workload increases.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Pulmonary circulation</strong></th>\n  <th><strong>Bronchial circulation</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Origin and role</td>\n  <td>Right ventricle; gas exchange.</td>\n  <td>Aortic branches; nourish airways.</td>\n</tr>\n<tr>\n  <td>Pressure</td>\n  <td>Low pressure.</td>\n  <td>Systemic arterial pressure.</td>\n</tr>\n<tr>\n  <td>Drainage</td>\n  <td>Pulmonary veins to left atrium.</td>\n  <td>Partly drains into pulmonary veins.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Systemic response to hypoxia</strong></th>\n  <th><strong>Pulmonary response to hypoxia</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Vascular change</td>\n  <td>Arterioles usually dilate.</td>\n  <td>Small pulmonary arteries constrict.</td>\n</tr>\n<tr>\n  <td>Purpose</td>\n  <td>Deliver more oxygen to oxygen-starved tissues.</td>\n  <td>Divert flow away from poorly ventilated alveoli.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Recruitment</strong></th>\n  <th><strong>Distension</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Vascular change</td>\n  <td>Previously closed/underperfused capillaries open.</td>\n  <td>Already open capillaries widen.</td>\n</tr>\n<tr>\n  <td>Effect</td>\n  <td>More parallel pathways reduce resistance.</td>\n  <td>Larger vessel calibre reduces resistance.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Pulmonary pressure</strong> should equal systemic pressure because flows are equal → Truth: Lower pulmonary resistance permits equal flow at much lower pressure.</li>\n<li>Trap: <strong>Exercise</strong> must greatly raise pulmonary pressure → Truth: Recruitment and distension accommodate more flow with modest pressure change.</li>\n<li>Trap: <strong>Most pulmonary blood flow</strong> occurs at the apex while upright → Truth: Gravity normally favours perfusion at the lung bases.</li>\n<li>Trap: <strong>Zone 1</strong> is present in every healthy lung → Truth: Alveolar pressure exceeding arterial pressure generally requires low pressure or positive-pressure ventilation.</li>\n<li>Trap: <strong>Lying flat</strong> eases left-failure breathlessness → Truth: More blood enters lung vessels and worsens pulmonary congestion.</li>\n<li>Trap: <strong>Low alveolar oxygen</strong> dilates pulmonary arteries as in other organs → Truth: Pulmonary vasoconstriction diverts blood towards better ventilated alveoli.</li>\n<li>Trap: <strong>Generalised hypoxia</strong> improves pulmonary distribution without cost → Truth: Widespread constriction raises pressure and strains the right ventricle.</li>\n</ul>\n"},{"slug":"splanchnic","must":[{"star":false,"html":"<strong>Coeliac trunk</strong> supplies upper abdominal digestive territories as one of three unpaired aortic branches serving the gut."},{"star":false,"html":"<strong>Superior and inferior mesenteric arteries</strong> supply most remaining intestinal territories from the abdominal aorta."},{"star":true,"html":"<strong>Hepatic portal route</strong> sends gut venous blood through the liver before systemic return so absorbed nutrients, drugs and toxins are processed."},{"star":false,"html":"<strong>Two capillary beds</strong> lie in series along the portal pathway: intestinal capillaries followed by hepatic sinusoids."},{"star":false,"html":"<strong>Portal vein formation</strong> involves superior mesenteric and splenic veins → venous blood from gut/spleen enters the liver."},{"star":true,"html":"<strong>Dual hepatic inflow</strong> supplies blood through portal vein and hepatic artery, mixing in liver sinusoids before venous drainage."},{"star":false,"html":"<strong>Portal venous blood</strong> delivers nutrient-rich but partly deoxygenated blood from intestine to the liver."},{"star":false,"html":"<strong>Hepatic arterial blood</strong> supplies oxygen-rich blood to liver tissue despite contributing less of its total flow."},{"star":false,"html":"<strong>Portal triad</strong> contains branches of portal vein, hepatic artery and bile duct → incoming blood and outgoing bile meet anatomically."},{"star":false,"html":"<strong>Liver sinusoidal flow</strong> moves from portal-triad branches towards central veins → hepatic veins drain into inferior vena cava."},{"star":false,"html":"<strong>Bile flow</strong> travels opposite sinusoidal blood, towards bile ducts near portal triads."},{"star":true,"html":"<strong>Zone 1 hepatocytes</strong> lie near portal triads and receive the most oxygenated sinusoidal inflow."},{"star":false,"html":"<strong>Zone 3 hepatocytes</strong> lie near central veins and receive less oxygen → hypoperfusion injures them first."},{"star":false,"html":"<strong>Space of Disse</strong> lies between liver sinusoids and hepatocytes → filtered fluid can become hepatic lymph."},{"star":false,"html":"<strong>Postprandial hyperaemia</strong> increases intestinal blood flow after meals because greater digestive activity produces local metabolic vasodilatation."},{"star":false,"html":"<strong>Large splanchnic venous reservoir</strong> stores blood in compliant veins → sympathetic constriction can mobilise it during haemorrhage."},{"star":false,"html":"<strong>Splanchnic sympathetic vasoconstriction</strong> redirects blood towards heart and brain during shock, but prolonged low gut flow risks ischaemia."},{"star":false,"html":"<strong>Intestinal mucosal flow</strong> is prominent because absorption and metabolism create substantial local perfusion demand."},{"star":false,"html":"<strong>Ascites</strong> means fluid accumulation within the peritoneal cavity from excessive filtration and inadequate fluid clearance."},{"star":true,"html":"<strong>Portal hypertension</strong> raises hepatic sinusoidal hydrostatic pressure → excessive fluid filtration and lymph production promote ascites."},{"star":false,"html":"<strong>Hepatic lymph overflow</strong> allows fluid to enter the abdomen when leaky sinusoids produce more lymph than drainage can handle."},{"star":false,"html":"<strong>Low plasma albumin</strong> reduces vascular oncotic pressure → fluid is less effectively retained inside capillaries."},{"star":false,"html":"<strong>Renal sodium/water retention</strong> adds circulating fluid → persistent portal hypertension can worsen ascitic accumulation."},{"star":false,"html":"<strong>Right heart failure</strong> raises hepatic venous pressure backwards → liver congestion can also cause ascites."},{"star":false,"html":"<strong>Ascitic fluid protein</strong> varies by cause; porous liver sinusoids do not mean every form of ascites has high protein."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Main gut arteries from aorta</td>\n  <td>3</td>\n  <td>Coeliac trunk plus superior and inferior mesenteric arteries.</td>\n</tr>\n<tr>\n  <td>Portal vein share of hepatic blood flow</td>\n  <td>About 75%</td>\n  <td>Major venous delivery of gut-derived nutrients.</td>\n</tr>\n<tr>\n  <td>Hepatic artery share of hepatic blood flow</td>\n  <td>About 25%</td>\n  <td>Smaller-volume supply contributes around half the oxygen.</td>\n</tr>\n<tr>\n  <td>Hepatic arterial oxygen contribution</td>\n  <td>About 50%</td>\n  <td>Oxygen delivery cannot be inferred from blood-flow share alone.</td>\n</tr>\n<tr>\n  <td>Duration of increased intestinal flow after a meal</td>\n  <td>About 3 hours (lecture slide)</td>\n  <td>Represents sustained digestive hyperaemia after eating.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Hepatic portal flow</strong>: Coeliac/mesenteric inflow perfuses gut → venous blood enters portal vein → hepatic sinusoids process absorbed substances → central veins → hepatic veins → inferior vena cava.</li>\n<li><strong>Hepatic oxygen gradient</strong>: Portal and hepatic arterial blood mix near portal triads → blood loses oxygen travelling towards central veins → zone 3 receives less oxygen → zone 3 is injured first during hypoperfusion.</li>\n<li><strong>Haemorrhage mobilisation</strong>: Blood volume falls → sympathetic drive constricts splanchnic vessels and veins → stored blood returns centrally → heart/brain perfusion is prioritised while gut ischaemia risk rises.</li>\n<li><strong>Ascites</strong>: Portal or hepatic venous pressure increases → sinusoidal filtration and hepatic lymph rise → lymphatic drainage is overwhelmed → fluid enters the peritoneum; low albumin and renal retention worsen it.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Portal vein</strong></th>\n  <th><strong>Hepatic artery</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Blood type</td>\n  <td>Nutrient-rich, partly deoxygenated venous blood.</td>\n  <td>Oxygen-rich arterial blood.</td>\n</tr>\n<tr>\n  <td>Approximate liver flow share</td>\n  <td>75%.</td>\n  <td>25%.</td>\n</tr>\n<tr>\n  <td>Role</td>\n  <td>Sends absorbed gut products through liver processing.</td>\n  <td>Contributes substantially to liver oxygen delivery.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Zone 1 near portal triad</strong></th>\n  <th><strong>Zone 3 near central vein</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Oxygen supply</td>\n  <td>Higher, because blood has just entered sinusoids.</td>\n  <td>Lower, after upstream hepatocytes have extracted oxygen.</td>\n</tr>\n<tr>\n  <td>Ischaemic injury</td>\n  <td>Relatively better protected.</td>\n  <td>Especially vulnerable during shock.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Portal hypertension in cirrhosis</strong></th>\n  <th><strong>Hepatic congestion in right failure</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Main pressure origin</td>\n  <td>Resistance to portal flow within scarred liver.</td>\n  <td>High systemic venous pressure backs into hepatic veins.</td>\n</tr>\n<tr>\n  <td>Shared result</td>\n  <td>Greater sinusoidal filtration and ascites.</td>\n  <td>Greater sinusoidal filtration and ascites.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Portal venous blood</strong> returns directly from gut to the heart → Truth: It passes through liver sinusoids first.</li>\n<li>Trap: <strong>Liver oxygen delivery</strong> follows its blood-flow shares exactly → Truth: The hepatic artery supplies a disproportionate share of oxygen.</li>\n<li>Trap: <strong>Zone 3</strong> is safest because it lies near central vein outflow → Truth: It receives the least oxygenated sinusoidal blood.</li>\n<li>Trap: <strong>Bile</strong> flows in the same direction as sinusoidal blood → Truth: Blood moves towards central veins while bile moves towards portal triads.</li>\n<li>Trap: <strong>Haemorrhage-related constriction</strong> cannot harm gut because it supports pressure → Truth: Prolonged severe reduction in gut flow can cause ischaemia.</li>\n<li>Trap: <strong>Ascites</strong> is always caused by low albumin alone → Truth: High sinusoidal pressure, lymph overflow and renal retention also contribute.</li>\n<li>Trap: <strong>Ascitic protein</strong> is invariably high due to fenestrated hepatic sinusoids → Truth: Protein level depends on the underlying cause.</li>\n</ul>\n"},{"slug":"skin","must":[{"star":true,"html":"<strong>Cutaneous blood flow</strong> is strongly regulated for heat exchange, so flow can exceed the skin's nutritional requirements."},{"star":false,"html":"<strong>Heat exposure</strong> widens skin vessels → more warm blood approaches the surface and heat loss increases."},{"star":false,"html":"<strong>Cold exposure</strong> increases sympathetic skin vasoconstriction → superficial flow falls and body heat is conserved."},{"star":false,"html":"<strong>Arteriovenous anastomoses</strong> provide shortcuts between small skin arteries and veins → warm blood can rapidly reach superficial vessels."},{"star":false,"html":"<strong>Arteriovenous shunts</strong> are prominent in fingers, toes, palms, ears and nose, where sympathetic control adjusts heat transfer."},{"star":true,"html":"<strong>Haemorrhagic shock</strong> increases sympathetic skin vasoconstriction → pale, cold skin appears as flow is diverted to heart and brain."},{"star":false,"html":"<strong>Early septic shock</strong> can cause warm flushed skin because circulating mediators dilate cutaneous vessels."},{"star":false,"html":"<strong>Skin temperature alone</strong> cannot determine shock type because peripheral flow varies with vascular tone and systemic state."},{"star":true,"html":"<strong>White skin reaction</strong> after a light stroke is brief pallor from local constriction; it is separate from Lewis's triple response."},{"star":false,"html":"<strong>Red line</strong> after a firm skin stroke comes from local capillary dilatation along the point of contact."},{"star":false,"html":"<strong>Flare</strong> is spreading redness around a stroke because sensory-nerve branches trigger nearby arteriolar dilation."},{"star":false,"html":"<strong>Wheal</strong> is a raised swelling because histamine increases local capillary and postcapillary venular permeability → fluid enters tissue."},{"star":true,"html":"<strong>Lewis triple response</strong> proceeds through red line → spreading flare → raised wheal after firm mechanical stimulation."},{"star":false,"html":"<strong>Sensory axon branching</strong> spreads signals from the stimulated branch into neighbouring branches without needing a spinal-cord synapse."},{"star":false,"html":"<strong>Antidromic conduction</strong> describes an impulse travelling back along collateral sensory nerve branches towards peripheral endings."},{"star":false,"html":"<strong>Substance P and CGRP</strong> released from peripheral sensory endings dilate local arterioles → redness spreads beyond the stroked line."},{"star":false,"html":"<strong>Mast-cell histamine</strong> promotes local vasodilatation and capillary leak → the wheal develops near the injured area."},{"star":true,"html":"<strong>Axon reflex</strong> generates the flare entirely through branches of one sensory fibre, rather than a conventional central reflex arc."},{"star":false,"html":"<strong>Local anaesthesia</strong> abolishes the flare by blocking sensory conduction, while purely local red-line and wheal components can remain."},{"star":false,"html":"<strong>Sensory nerve degeneration</strong> removes the flare because an intact peripheral axon is needed for antidromic signalling."},{"star":false,"html":"<strong>Nerve interruption above the branch point</strong> may preserve flare because the reflex does not require transmission to the spinal cord."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Approximate white-line duration (lecture)</td>\n  <td>About 15 seconds</td>\n  <td>Short-lived constriction from a light skin stroke.</td>\n</tr>\n<tr>\n  <td>Components of Lewis's triple response</td>\n  <td>3</td>\n  <td>Red line, flare and wheal are distinct local mechanisms.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Thermoregulatory vasodilatation</strong>: Skin warms → superficial arterioles/arteriovenous shunts open → warm blood reaches skin surface → body heat is lost.</li>\n<li><strong>Haemorrhage-related pallor</strong>: Arterial volume falls → sympathetic discharge increases → cutaneous vessels constrict → skin flow decreases → skin becomes cold and pale.</li>\n<li><strong>Axon-reflex flare</strong>: Firm stroke stimulates a sensory branch → impulses enter collateral branches antidromically → substance P/CGRP are released → surrounding arterioles dilate → flare spreads.</li>\n<li><strong>Wheal formation</strong>: Firm stroke triggers local inflammatory mediator release → histamine increases small-vessel permeability → plasma fluid enters the dermis → raised swelling develops.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>White line</strong></th>\n  <th><strong>Red line</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Stimulus</td>\n  <td>Light mechanical stroke.</td>\n  <td>Firmer stroke.</td>\n</tr>\n<tr>\n  <td>Vascular response</td>\n  <td>Local constriction and transient pallor.</td>\n  <td>Local capillary dilation and redness.</td>\n</tr>\n<tr>\n  <td>Relation to triple response</td>\n  <td>Not part of it.</td>\n  <td>First component.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Flare</strong></th>\n  <th><strong>Wheal</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Appearance</td>\n  <td>Spreading red area.</td>\n  <td>Local raised swelling.</td>\n</tr>\n<tr>\n  <td>Main mechanism</td>\n  <td>Sensory axon reflex dilates arterioles.</td>\n  <td>Histamine increases capillary permeability.</td>\n</tr>\n<tr>\n  <td>Dependence on sensory nerve</td>\n  <td>Requires intact peripheral axon branches.</td>\n  <td>Primarily a local permeability response.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Axon reflex</strong></th>\n  <th><strong>Central reflex arc</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Neural pathway</td>\n  <td>Peripheral branches of one sensory neuron.</td>\n  <td>Afferent signals enter the CNS and return by efferents.</td>\n</tr>\n<tr>\n  <td>Spinal cord needed</td>\n  <td>No.</td>\n  <td>Yes for a spinal reflex.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Skin flow</strong> is controlled chiefly by nutritional demand → Truth: Its large changes primarily regulate heat exchange.</li>\n<li>Trap: <strong>Cold shock skin</strong> proves every tissue has low flow equally → Truth: Sympathetic redistribution preserves vital organs relatively.</li>\n<li>Trap: <strong>Early septic shock</strong> must produce cold pale skin → Truth: Peripheral vasodilatation can make skin warm.</li>\n<li>Trap: <strong>The white line</strong> is one of Lewis's three reactions → Truth: The triple response is red line, flare and wheal.</li>\n<li>Trap: <strong>Flare</strong> is caused by histamine leakage alone → Truth: It spreads through an axon reflex that dilates nearby arterioles.</li>\n<li>Trap: <strong>Axon reflex</strong> needs an impulse to reach the spinal cord → Truth: Collateral branches within the peripheral nerve fibre carry the response.</li>\n<li>Trap: <strong>Wheal</strong> means an area of arteriolar constriction → Truth: Increased vascular permeability allows oedema to form.</li>\n</ul>\n"},{"slug":"fetal","must":[{"star":true,"html":"<strong>Placenta</strong> performs fetal gas exchange because the unborn lungs are fluid-filled and do not yet ventilate air."},{"star":false,"html":"<strong>High fetal pulmonary resistance</strong> keeps most right ventricular output from flowing through the unventilated lungs."},{"star":false,"html":"<strong>Low placental vascular resistance</strong> provides a large low-resistance circuit before birth → systemic resistance is comparatively low."},{"star":true,"html":"<strong>Single umbilical vein</strong> brings oxygenated placental blood towards the fetal liver and inferior vena cava."},{"star":false,"html":"<strong>Ductus venosus</strong> channels much umbilical venous blood towards the inferior vena cava → most of that stream bypasses liver sinusoids."},{"star":false,"html":"<strong>IVC blood streaming</strong> directs comparatively oxygen-rich blood towards the foramen ovale in the fetal right atrium."},{"star":false,"html":"<strong>Foramen ovale</strong> passes blood from right atrium to left atrium → oxygen-rich inflow can reach left ventricle and upper aorta."},{"star":false,"html":"<strong>Best-oxygenated fetal blood</strong> preferentially supplies the heart and brain through left-heart outflow from the foramen ovale."},{"star":false,"html":"<strong>Superior vena cava blood</strong> preferentially enters right ventricle → pulmonary trunk receives relatively oxygen-poor blood."},{"star":false,"html":"<strong>Ductus arteriosus</strong> diverts pulmonary trunk blood into descending aorta → most blood bypasses high-resistance fetal lungs."},{"star":false,"html":"<strong>Two umbilical arteries</strong> return fetal blood from internal iliac branches to the placenta for reoxygenation."},{"star":true,"html":"<strong>Right-to-left fetal shunting</strong> occurs because high lung resistance and low placental resistance favour right-sided pressures before birth."},{"star":false,"html":"<strong>Fetal haemoglobin (HbF)</strong> binds oxygen more tightly than adult HbA because its interaction with 2,3-BPG is weaker."},{"star":false,"html":"<strong>Reduced HbF binding to 2,3-BPG</strong> shifts oxygen affinity upward → oxygen can be transferred from maternal haemoglobin at placental exchange surfaces."},{"star":false,"html":"<strong>Placental oxygen saturation</strong> is below adult arterial levels, making HbF's higher oxygen affinity especially valuable."},{"star":false,"html":"<strong>HbF replacement</strong> occurs gradually after birth as adult haemoglobin synthesis increases over the following months."},{"star":true,"html":"<strong>First newborn breaths</strong> expand oxygenated lungs → pulmonary vessels dilate, pulmonary resistance falls and pulmonary venous return increases."},{"star":false,"html":"<strong>Cord clamping</strong> removes the low-resistance placenta → systemic vascular resistance rises and umbilical venous flow stops."},{"star":false,"html":"<strong>Left atrial pressure rise</strong> after breathing exceeds right atrial pressure → the foramen ovale flap closes functionally."},{"star":false,"html":"<strong>Higher postnatal oxygen and lower prostaglandins</strong> cause ductus arteriosus constriction → fetal pulmonary bypass closes."},{"star":false,"html":"<strong>Stopped umbilical flow</strong> promotes ductus venosus closure because its placental blood source has been removed."},{"star":false,"html":"<strong>Functional closure</strong> changes flow within minutes to days, whereas anatomical fibrous closure develops over weeks to months."},{"star":false,"html":"<strong>Fossa ovalis</strong> is the adult remnant of the foramen ovale after atrial septal flap fusion."},{"star":false,"html":"<strong>Ligamentum arteriosum</strong> is the fibrous remnant of the ductus arteriosus joining pulmonary trunk and aortic regions."},{"star":false,"html":"<strong>Ligamentum venosum</strong> marks the former ductus venosus within the liver."},{"star":false,"html":"<strong>Ligamentum teres hepatis</strong> is the remnant of the fetal umbilical vein."},{"star":false,"html":"<strong>Medial umbilical ligaments</strong> are remnants of the distal umbilical arteries after placental flow ceases."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Fetal umbilical vein</td>\n  <td>1</td>\n  <td>Returns comparatively oxygen-rich blood from placenta.</td>\n</tr>\n<tr>\n  <td>Fetal umbilical arteries</td>\n  <td>2</td>\n  <td>Carry blood back to the placenta.</td>\n</tr>\n<tr>\n  <td>Major fetal shunts</td>\n  <td>3</td>\n  <td>Ductus venosus, foramen ovale and ductus arteriosus bypass liver or lungs.</td>\n</tr>\n<tr>\n  <td>Approximate oxygen saturation of umbilical venous blood</td>\n  <td>About 80%</td>\n  <td>Fetal blood is less saturated than adult systemic arterial blood.</td>\n</tr>\n<tr>\n  <td>Lecturer's approximate HbF decline reference</td>\n  <td>Around 4 months after birth</td>\n  <td>HbF is progressively replaced by HbA; avoid treating the change as instantaneous.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Fetal oxygenated route</strong>: Placenta → umbilical vein → ductus venosus → inferior vena cava → right atrium → foramen ovale → left atrium/ventricle → ascending aorta → heart and brain.</li>\n<li><strong>Fetal pulmonary bypass</strong>: Superior vena cava → right atrium → right ventricle → pulmonary trunk → ductus arteriosus → descending aorta → umbilical arteries → placenta.</li>\n<li><strong>Foramen ovale closure</strong>: First breath increases lung oxygen → pulmonary resistance falls → more blood reaches left atrium; cord clamping raises systemic resistance → left atrial pressure exceeds right → flap shuts.</li>\n<li><strong>Ductus arteriosus closure</strong>: Placenta is disconnected and lungs oxygenate blood → prostaglandins fall and arterial oxygen rises → ductus arteriosus constricts → ligamentum arteriosum eventually forms.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Ductus venosus</strong></th>\n  <th><strong>Ductus arteriosus</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Connection</td>\n  <td>Umbilical vein towards inferior vena cava.</td>\n  <td>Pulmonary trunk towards descending aorta.</td>\n</tr>\n<tr>\n  <td>Main bypass</td>\n  <td>Liver.</td>\n  <td>Lungs.</td>\n</tr>\n<tr>\n  <td>Adult remnant</td>\n  <td>Ligamentum venosum.</td>\n  <td>Ligamentum arteriosum.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Foramen ovale before birth</strong></th>\n  <th><strong>Foramen ovale after birth</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Atrial pressure</td>\n  <td>Right atrial side relatively higher.</td>\n  <td>Left atrial pressure becomes higher.</td>\n</tr>\n<tr>\n  <td>Blood movement</td>\n  <td>Right-to-left atrial shunting.</td>\n  <td>Flap closes and functional shunt ends.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>HbF</strong></th>\n  <th><strong>HbA</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>2,3-BPG binding</td>\n  <td>Weaker binding.</td>\n  <td>Stronger binding.</td>\n</tr>\n<tr>\n  <td>Oxygen affinity</td>\n  <td>Higher, favouring placental oxygen uptake.</td>\n  <td>Lower, favouring peripheral oxygen unloading.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Fetal lungs</strong> are the principal oxygen exchanger → Truth: Placenta supplies fetal oxygen while pulmonary resistance is high.</li>\n<li>Trap: <strong>Umbilical arteries</strong> carry the oxygen-rich blood towards fetus → Truth: The single umbilical vein carries oxygenated blood towards fetus.</li>\n<li>Trap: <strong>Ductus venosus</strong> bypasses lungs → Truth: It bypasses much of the liver; ductus arteriosus and foramen ovale bypass pulmonary flow.</li>\n<li>Trap: <strong>Foramen ovale</strong> shunts left-to-right before birth → Truth: Higher right-sided pressure supports right-to-left flow.</li>\n<li>Trap: <strong>HbF</strong> binds more 2,3-BPG and therefore has higher oxygen affinity → Truth: HbF binds 2,3-BPG less strongly, increasing affinity.</li>\n<li>Trap: <strong>Cord clamping</strong> lowers systemic resistance → Truth: Removing the low-resistance placenta raises systemic resistance.</li>\n<li>Trap: <strong>First breaths</strong> increase pulmonary vascular resistance → Truth: Oxygenation and lung expansion lower resistance markedly.</li>\n<li>Trap: <strong>All fetal shunts</strong> seal anatomically the instant breathing begins → Truth: Functional changes precede fibrous anatomical closure.</li>\n</ul>\n"}]};
